},{"v":"M9BA","label":"D-M9BA, 2-tråd, vattentät, rak"},{"v":"M9NAV","label":"D-M9NAV, NPN, vattentät, vinklad"},{"v":"M9PAV","label":"D-M9PAV, PNP, vattentät, vinklad"},{"v":"M9BAV","label":"D-M9BAV, 2-tråd, vattentät, vinklad"},{"v":"P3DW","label":"D-P3DW, 2-tråd, magnetfältstålig (ø32–100)"},{"v":"A96","label":"D-A96, reed 3-tråd, rak"},{"v":"A93","label":"D-A93, reed 2-tråd, rak"},{"v":"A90","label":"D-A90, reed 2-tråd utan indikering, rak"},{"v":"A96V","label":"D-A96V, reed 3-tråd, vinklad"},{"v":"A93V","label":"D-A93V, reed 2-tråd, vinklad"},{"v":"A90V","label":"D-A90V, reed 2-tråd utan indikering, vinklad"}]},{"id":"lead","step":13,"title_sv":"Givarens kabellängd","title_en":"Lead wire length","required":false,"type":"single_select","options":[{"v":"M","label":"1 m kabel"},{"v":"L","label":"3 m kabel"},{"v":"Z","label":"5 m kabel"}]},{"id":"count","step":14,"title_sv":"Antal givare","title_en":"Number of auto switches","required":false,"type":"single_select","options":[{"v":"S","label":"1 givare (standard är 2)"}]},{"id":"mto","step":15,"title_sv":"Specialutförande","title_en":"Made to order","required":false,"type":"single_select","options":[{"v":"XA","label":"-XA Ändrad kolvstångsände (enkelverkande: bara fjäderretur)"},{"v":"XB6","label":"-XB6 Värmebeständig –10…150 °C (utan givare)"},{"v":"XB7","label":"-XB7 Köldbeständig –40…70 °C (utan givare)"},{"v":"XB9","label":"-XB9 Låg hastighet 10–50 mm/s"},{"v":"XB10","label":"-XB10 Mellanslag, egen kropp (enkelverkande: bara fjäderretur)"},{"v":"XB10A","label":"-XB10A Mellanslag 51 mm eller mer, distans (ø32–100)"},{"v":"XB11","label":"-XB11 Långt slag (bara luft-hydraulik)"},{"v":"XB13","label":"-XB13 Låg hastighet 5–50 mm/s"},{"v":"XB14","label":"-XB14 Värmebeständig givare (ø16–63)"},{"v":"XC2","label":"-XC2 Kolvstångsände 10 mm längre (fot- och flänsfäste)"},{"v":"XC4","label":"-XC4 Kraftig avstrykare (ø20–100)"},{"v":"XC6","label":"-XC6 Kolvstång, låsring och mutter i rostfritt"},{"v":"XC8","label":"-XC8 Ju