from products p where s.product_id = p.id and p.sku = 'SMC-CQ2B63' and s.key = 'stroke_mm' and s.value = '300 mm';

insert into product_specs (product_id, key, value)
select p.id, x.key, x.value
from products p
cross join lateral (values
  ('standard_strokes_mm', '10, 15, 20, 25, 30, 35, 40, 45, 50, 75, 100'),
  ('force_out_n_05mpa', '1560'),
  ('min_pressure_mpa', '0.05'),
  ('order_code_example', 'CQ2B63-100DZ'),
  ('catalogue', 'SMC CQ2, How to Order sida 785, data sida 786')
) as x(key, value)
where p.sku = 'SMC-CQ2B63'
  and not exists (select 1 from product_specs y where y.product_id = p.id and y.key = x.key);


commit;

